def broadcast_tensor_dict(
    tensor_dict: dict[Any, torch.Tensor | Any] | None = None, src: int = 0
):
    if not torch.distributed.is_initialized():
        return tensor_dict
    return get_tp_group().broadcast_tensor_dict(tensor_dict, src)

def forward(
    self,
    input_,
) -> torch.Tensor | tuple[torch.Tensor, Parameter | None]:
    if self.input_is_parallel:
        input_parallel = input_
    else:
        split_input = split_tensor_along_last_dim(
            input_, num_partitions=self.tp_size
        )
        input_parallel = split_input[self.tp_rank].contiguous()

    # Matrix multiply.
    # Only fuse bias add into GEMM for rank 0 (this ensures that
    # bias will not get added more than once in TP>1 case)
    bias_ = None if (self.tp_rank > 0 or self.skip_bias_add) else self.bias
    output_parallel = self.quant_method.apply(self, input_parallel, bias_)

    if self.reduce_results and self.tp_size > 1:
        output = tensor_model_parallel_all_reduce(output_parallel)
    else:
        output = output_parallel

    if not self.return_bias:
        return output
    output_bias = self.bias if self.skip_bias_add else None
    return output, output_bias

class AsyncIntermediateTensors(IntermediateTensors):
    """IntermediateTensors with lazy comm synchronization"""

    def __init__(
        self,
        tensors: dict[str, torch.Tensor],
        comm_handles: list[Handle] | None = None,
        comm_postprocess: list[Callable[[], None]] | None = None,
    ) -> None:
        super().__init__(tensors)
        self._comm_handles = comm_handles
        self._comm_postprocess = comm_postprocess
        self._comm_waited = False

    def wait_for_comm(self) -> None:
        if self._comm_waited:
            return
        if self._comm_handles:
            for handle in self._comm_handles:
                handle.wait()
        if self._comm_postprocess:
            for fn in self._comm_postprocess:
                fn()
        self._comm_waited = True

    def __getattribute__(self, name: str):
        # ensure `.tensors` is ready before use
        if name == "tensors" and not object.__getattribute__(self, "_comm_waited"):
            object.__getattribute__(self, "wait_for_comm")()
        return object.__getattribute__(self, name)

@torch.inference_mode()
@with_gpu_sync_check
def execute_model(
    self, scheduler_output: "SchedulerOutput"
) -> ModelRunnerOutput | AsyncModelRunnerOutput | None:
    # ensure any previous non-blocking PP sends are complete
    if self._pp_send_work:
        for handle in self._pp_send_work:
            handle.wait()
        self._pp_send_work = []

    intermediate_tensors = None
    forward_pass = scheduler_output.total_num_scheduled_tokens > 0
    num_scheduled_tokens = scheduler_output.total_num_scheduled_tokens
    all_gather_tensors = {}
    compilation_config = self.vllm_config.compilation_config
    parallel_config = self.vllm_config.parallel_config

    if (
        parallel_config.pipeline_parallel_size > 1
        and compilation_config.pass_config.enable_sp
        and forward_pass
    ):
        # currently only supported by V1 GPUModelRunner
        assert not self.use_v2_model_runner
        num_scheduled_tokens_np = np.array(
            list(scheduler_output.num_scheduled_tokens.values()),
            dtype=np.int32,
        )
        # TODO(lucas): This is pretty gross; ideally we should only ever call
        # `_determine_batch_execution_and_padding` once (will get called again
        # in `execute_model`) but this requires a larger refactor of PP.
        _, batch_desc, _, _, _ = (
            self.model_runner._determine_batch_execution_and_padding(
                num_tokens=num_scheduled_tokens,
                num_reqs=len(num_scheduled_tokens_np),
                num_scheduled_tokens_np=num_scheduled_tokens_np,
                max_num_scheduled_tokens=num_scheduled_tokens_np.max(),
                use_cascade_attn=False,  # TODO(lucas): Handle cascade attention
            )
        )
        all_gather_tensors = {
            "residual": not is_residual_scattered_for_sp(
                self.vllm_config, batch_desc.num_tokens
            )
        }

    if forward_pass and not get_pp_group().is_first_rank:
        tensor_dict, comm_handles, comm_postprocess = (
            get_pp_group().irecv_tensor_dict(
                all_gather_group=get_tp_group(),
                all_gather_tensors=all_gather_tensors,
            )
        )
        assert tensor_dict is not None
        intermediate_tensors = AsyncIntermediateTensors(
            tensor_dict,
            comm_handles=comm_handles,
            comm_postprocess=comm_postprocess,
        )

    with self.annotate_profile(scheduler_output):
        output = self.model_runner.execute_model(
            scheduler_output, intermediate_tensors
        )
        if (
            self.use_v2_model_runner
            and self.model_runner.is_pooling_model
            and output is None
        ):
            output = self.model_runner.pool()  # type: ignore
        if isinstance(
            output, ModelRunnerOutput | AsyncModelRunnerOutput | NoneType
        ):
            return output

    assert isinstance(output, IntermediateTensors)
    parallel_config = self.vllm_config.parallel_config
    assert (
        parallel_config.distributed_executor_backend != "external_launcher"
        and not get_pp_group().is_last_rank
    )

    # launch non-blocking send of intermediate tensors
    self._pp_send_work = get_pp_group().isend_tensor_dict(
        output.tensors,
        all_gather_group=get_tp_group(),
        all_gather_tensors=all_gather_tensors,
    )

    return None

def isend_tensor_dict(
    self,
    tensor_dict: dict[str, torch.Tensor | Any],
    dst: int | None = None,
    all_gather_group: "GroupCoordinator | None" = None,
    all_gather_tensors: dict[str, bool] | None = None,
) -> list[Handle]:
    if self.world_size <= 1:
        return []

    if dst is None:
        dst = (self.rank_in_group + 1) % self.world_size
    assert dst < self.world_size, f"Invalid dst rank ({dst})"

    if self.use_cpu_custom_send_recv:
        if self.device_communicator is None:
            raise ValueError("No device communicator found")
        # custom device communicator path is synchronous
        self.device_communicator.send_tensor_dict(  # type: ignore
            tensor_dict, dst
        )
        return []

    all_gather_size = 1 if all_gather_group is None else all_gather_group.world_size
    all_gather_rank = (
        0 if all_gather_group is None else all_gather_group.rank_in_group
    )

    group = self.device_group
    metadata_group = self.cpu_group

    metadata_list, tensor_list = _split_tensor_dict(tensor_dict)
    self.send_object(metadata_list, dst=dst)

    tensor_keys = [k for k, v in tensor_dict.items() if isinstance(v, torch.Tensor)]
    assert len(tensor_keys) == len(tensor_list)

    handles: list[Handle] = []
    for key, tensor in zip(tensor_keys, tensor_list):
        if tensor.numel() == 0:
            continue

        if self._should_use_all_gather(
            key, tensor.numel(), all_gather_group, all_gather_tensors
        ):
            tensor = tensor.reshape(all_gather_size, -1)[all_gather_rank]

        comm_group = metadata_group if tensor.is_cpu else group
        handle = torch.distributed.isend(
            tensor, dst=self.ranks[dst], group=comm_group
        )
        if tensor.is_cuda:
            tensor.record_stream(torch.cuda.current_stream(tensor.device))
        handles.append(handle)

    return handles

def make_async_mp_client(
    vllm_config: VllmConfig,
    executor_class: type[Executor],
    log_stats: bool,
    client_addresses: dict[str, Any] | None = None,
    client_count: int = 1,
    client_index: int = 0,
) -> "AsyncMPClient":
    parallel_config = vllm_config.parallel_config
    client_args = (
        vllm_config,
        executor_class,
        log_stats,
        client_addresses,
        client_count,
        client_index,
    )
    if parallel_config.data_parallel_size > 1:
        if parallel_config.data_parallel_external_lb:
            # External load balancer - client per DP rank.
            return DPAsyncMPClient(*client_args)
        # Internal load balancer - client balances to all DP ranks.
        return DPLBAsyncMPClient(*client_args)
    return AsyncMPClient(*client_args)

def _post_process_dp_padding(tensor: torch.Tensor, should_dp_pad: bool) -> torch.Tensor:
    num_tokens_across_dp = tensor[1, :]
    if should_dp_pad:
        # If DP padding is enabled, ensure that each rank is processing the same number
        # of tokens
        max_num_tokens = int(num_tokens_across_dp.max().item())
        return torch.tensor(
            [max_num_tokens] * len(num_tokens_across_dp),
            device="cpu",
            dtype=torch.int32,
        )
    else:
        return num_tokens_across_dp.cpu()

class AgRsAll2AllManager(All2AllManagerBase):
    """
    An implementation of all2all communication based on
    all-gather (dispatch) and reduce-scatter (combine).
    """

    def __init__(self, cpu_group, tcp_store_group=None):
        super().__init__(cpu_group, tcp_store_group)

    def _get_comm_group(self, is_sequence_parallel: bool) -> Any:
        if is_sequence_parallel:
            return get_ep_group()
        if self.dp_world_size > 1:
            return get_dp_group()
        return get_pcp_group()

    def _get_sizes(self, num_local_tokens: int, comm_group: Any) -> list[int]:
        if self.dp_world_size == 1:
            return [num_local_tokens] * comm_group.world_size

        dp_metadata = get_forward_context().dp_metadata
        assert dp_metadata is not None
        sizes = dp_metadata.get_chunk_sizes_across_dp_rank()
        assert sizes is not None

class IntermediateTensors:
    """For all pipeline stages except the last, we need to return the hidden
    states and residuals to be sent to the next stage. This data structure
    contains the hidden states and residuals for a request.
    """

    tensors: dict[str, torch.Tensor]

    def __init__(
        self,
        tensors: dict[str, torch.Tensor],
    ) -> None:
        # manually define this function, so that
        # Dynamo knows `IntermediateTensors()` comes from this file.
        # Otherwise, dataclass will generate this function by evaluating
        # a string, and we will lose the information about the source file.
        self.tensors = tensors

    def __getitem__(self, key: str | slice):
        if isinstance(key, str):
            return self.tensors[key]
        elif isinstance(key, slice):
            return self.__class__({k: v[key] for k, v in self.tensors.items()})

    def __setitem__(self, key: str, value: torch.Tensor):
        self.tensors[key] = value
